  ". Please raise a Support Ticket to process paid event listing, ticketing, and gateway configuration.": ". ચૂકવણીવાળા કાર્યક્રમની યાદી, ટિકિટિંગ અને ગેટવે કૉન્ફિગરેશન માટે કૃપા કરીને સપોર્ટ ટિકિટ નોંધાવો.",
