  ".xlsx": ".xlsx",
  ".xlsx only · Max 10 MB": "ફક્ત .xlsx · મહત્તમ 10 MB",
  "· Category:": "· શ્રેણી:",
  "· Current:": "· વર્તમાન:",
  "· Device ID:": "· ડિવાઇસ આઈડી:",
  "\"Paid Events are managed exclusively by JiNANAM. If you wish to organize a paid event, please raise a support ticket. Our team will coordinate with you and create the event on your behalf.\"": "\"ચૂકવણીવાળા કાર્યક્રમો ફક્ત JiNANAM દ્વારા સંચાલિત થાય છે. જો તમે ચૂકવણીવાળો કાર્યક્રમ યોજવા માગતા હો, તો કૃપા કરીને સપોર્ટ ટિકિટ નોંધાવો. અમારી ટીમ તમારી સાથે સંકલન કરીને તમારા વતી કાર્યક્રમ બનાવશે.\"",
  "(all fields mandatory)": "(બધાં ફીલ્ડ ફરજિયાત)",
  "(all fields required *)": "(બધાં ફીલ્ડ જરૂરી *)",
  "(Auto-linked to current Temple/Jain Centre)": "(વર્તમાન મંદિર/જૈન કેન્દ્ર સાથે આપોઆપ જોડાયેલ)",
  "(case-insensitive). Column marked": "(અક્ષર-ભેદ રહિત). ચિહ્નિત કૉલમ",
  "(or tick Same as Current)": "(અથવા 'વર્તમાન જેવું જ' પર ટિક કરો)",
  "* Linking members as volunteers will automatically display \"Volunteer at this Dharamshala\" on their public member profile card.": "* સભ્યોને સ્વયંસેવક તરીકે જોડવાથી તેમના જાહેર સભ્ય પ્રોફાઇલ કાર્ડ પર \"આ ધર્મશાળામાં સ્વયંસેવક\" આપોઆપ દેખાશે.",
  "* Note: Rooms blocked or put on hold by the Admin will be displayed as \"booked\" to members, but remain flagged as Admin Blocked in backend control layers.": "* નોંધ: એડમિન દ્વારા બ્લૉક કરાયેલા કે હોલ્ડ પર મૂકાયેલા રૂમ સભ્યોને \"બુક\" દેખાશે, પરંતુ બૅકએન્ડ નિયંત્રણ સ્તરોમાં તે એડમિન બ્લૉક્ડ જ રહેશે.",
  "**Monk Admins** have a global scope and are not restricted to specific organizations.": "**મુનિ એડમિન**નો વ્યાપ વૈશ્વિક હોય છે અને તેઓ કોઈ ચોક્કસ સંસ્થા સુધી મર્યાદિત નથી.",
  "**Temple/Dharamshala/Jain Center Admins** must be mapped to at least one scoped organization. They can only CRUD resources inside their scoped organizations.": "**મંદિર/ધર્મશાળા/જૈન કેન્દ્ર એડમિન**ને ઓછામાં ઓછી એક નિર્દિષ્ટ સંસ્થા સાથે જોડવા જરૂરી છે. તેઓ ફક્ત પોતાની નિર્દિષ્ટ સંસ્થાઓમાં જ સંસાધનો બનાવી, જોઈ, બદલી કે દૂર કરી શકે છે.",
