  "Every meaningful screen listens to Socket.IO. When a monk moves, a visitor checks in, or a donation is verified — everyone with permission sees it within a heartbeat.": "દરેક મહત્ત્વની સ્ક્રીન Socket.IO સાથે જોડાયેલી છે. જ્યારે કોઈ મુનિ આગળ વધે, કોઈ મુલાકાતી ચેક-ઇન કરે કે કોઈ દાન ચકાસાય — પરવાનગી ધરાવતા સૌને તરત દેખાય છે.",
  "Every module respects role-based permissions. Super Admins get everything; temple / dharamshala / jain-center admins see only their scope.": "દરેક મોડ્યુલ ભૂમિકા-આધારિત પરવાનગીઓનું પાલન કરે છે. સુપર એડમિનને બધું મળે છે; મંદિર / ધર્મશાળા / જૈન-કેન્દ્ર એડમિનને ફક્ત પોતાનો વ્યાપ દેખાય છે.",
